test('REQ-3-1-1#audit-2: Rejected commit keeps original value and dependent results', async ({ page }) => {
  await createBlankWorkbook(page);
  await setCellViaFormulaBar(page, 'A1', '50');
  await setCellViaFormulaBar(page, 'B1', '=A1*2');
  await setNumberValidation(page, 'A1', 'A1', 0, 100);
  await cell(page, 'A1').dblclick();
  const editor = page.getByRole('textbox', { name: 'Edit A1', exact: true });
  await expect(editor).toBeVisible();
  await editor.fill('101');
  await editor.press('Enter');
  await expect(page.getByText('Please enter a number between 0 and 100', { exact: true })).toBeVisible();
  await expect(cell(page, 'A1')).toHaveText('50');
  await expect(cell(page, 'B1')).toHaveText('100');
  await cell(page, 'A1').click();
  await expect(formulaBar(page)).toHaveValue('50');
  await page.reload();
  await expect(cell(page, 'A1')).toHaveText('50');
  await expect(cell(page, 'B1')).toHaveText('100');
});
